def minBoxArea(image, x, y):
    m, n = len(image), len(image[0])

    def col_has(c):
        for i in range(m):
            if image[i][c]:
                return True
        return False

    def row_has(r):
        return 1 in image[r]

    lo, hi = 0, y
    while lo < hi:
        mid = (lo + hi) // 2
        if col_has(mid):
            hi = mid
        else:
            lo = mid + 1
    left = lo
    lo, hi = y, n - 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if col_has(mid):
            lo = mid
        else:
            hi = mid - 1
    right = lo
    lo, hi = 0, x
    while lo < hi:
        mid = (lo + hi) // 2
        if row_has(mid):
            hi = mid
        else:
            lo = mid + 1
    top = lo
    lo, hi = x, m - 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if row_has(mid):
            lo = mid
        else:
            hi = mid - 1
    bottom = lo
    return (bottom - top + 1) * (right - left + 1)
